function groupReplyPreview(text){
 const allLines=text.split(/\r?\n/u);
 if(Array.from(text).length<300&&allLines.length<12)return null;
 const passages=[];
 let fence=false;
 let questionSection=false;
 for(const line of allLines){
  if(/^\s*(?:\x60{3}|~{3})/u.test(line)){fence=!fence;continue;}
  if(fence||/^\s*[|>]/u.test(line))continue;
  const heading=/^\s{0,3}#{1,6}\s+/u.test(line);
  const plain=line.replace(/^\s{0,3}(?:#{1,6}\s+|[-*+]\s+|\d+[.)、]\s*)/u,"")
    .replace(/!?\[([^\]]+)\]\([^)]+\)/gu,"$1").replace(/[*_\x60~]/gu,"").trim();
  if(!plain)continue;
  const asks=/(?:你确认|你回答|你选择|你决定|待确认|待回答|待答问题|请确认|需要确认)/u.test(plain);
  if(heading)questionSection=asks;
  passages.push({plain,heading,important:asks||questionSection,question:/[？?]/u.test(plain)});
 }
 const summary=passages.find(row=>!row.heading&&!row.question&&row.plain.length>=18) ??
  passages.find(row=>!row.heading&&!row.question);
 const ask=passages.find(row=>!row.heading&&row.important&&row.question) ??
  passages.find(row=>!row.heading&&row.question) ?? passages.find(row=>!row.heading&&row.important&&row.plain.length>12);
 if(!summary&&!ask)return null;
 const shorten=(value,limit)=>{
  const chars=Array.from(value??"");
  return chars.length<=limit?chars.join(""):chars.slice(0,limit-1).join("")+"…";
 };
 const sentence=summary?.plain.match(/^.+?[。！？!?](?=\s|[\p{Script=Han}]|$)/u)?.[0]??summary?.plain;
 return {summary:shorten(sentence,120),question:ask===summary?"":shorten(ask?.plain,130)};
}
function GroupBotReply({entry,pauseFollowing}){
 const [expanded,setExpanded]=useState(false);
 const bubble=useRef(null),position=useRef(null),pending=useRef(null);
 const preview=useMemo(()=>groupReplyPreview(entry.text??""),[entry.text]);
 useLayoutEffect(()=>{
  if(pending.current===null||!bubble.current)return;
  const scroll=bubble.current.closest("[data-ac-transcript-scroll]");
  if(scroll)scroll.scrollTop+=bubble.current.getBoundingClientRect().top-scroll.getBoundingClientRect().top-pending.current;
  pending.current=null;
 },[expanded]);
 function toggle(){
  const scroll=bubble.current?.closest("[data-ac-transcript-scroll]");
  if(scroll){
   const offset=bubble.current.getBoundingClientRect().top-scroll.getBoundingClientRect().top;
   if(!expanded)position.current=offset;
   pending.current=expanded?position.current:offset;
   pauseFollowing();
  }
  setExpanded(value=>!value);
 }
 return jsxs("div",{className:"br-bubble br-bot-bubble",ref:bubble,children:[
  preview&&!expanded?jsxs("div",{className:"br-reply-preview",children:[
   preview.summary&&jsx("p",{children:preview.summary}),
   preview.question&&jsx("p",{className:"br-reply-question",children:preview.question})
  ]}):jsx(Markdown,{text:entry.text??""}),
  preview&&jsx("button",{className:"br-more-text",type:"button","aria-expanded":expanded,onClick:toggle,
   children:expanded?"收起全文":"展开全文"}),
  jsx(AttachmentRows,{attachments:entry.attachments,hasText:!!entry.text})
 ]});
}
function groupReplyRows(entries, runs, seen) {
  const rows = groupRows(entries);
  const parents = new Set(rows.filter(row => row.type === "user").map(row => row.messageId ?? row.id));
  const replies = new Set(rows.filter(row => row.type === "bot-text").map(row => row.runId));
  // Use the same run key and place in the conversation when the real reply replaces its placeholder.
  for (const run of runs) {
    const slot = seen.get(run.id);
    if (replies.has(run.id)) {
      if (slot) slot.published = true;
      continue;
    }
    const active = run.status === "running" || run.status === "queued";
    const failed = run.status === "failed" && !!run.originMessageId && parents.has(run.originMessageId);
    // The snapshot may settle before the independent ledger cursor publishes the final text.
    const finished = Date.parse(run.finishedAt ?? run.updatedAt);
    const publishing = run.status === "completed" && slot && !slot.published && Date.now()-finished < 15_000;
    if (!active && !failed && !publishing) continue;
    const at = slot?.at ?? run.createdAt ?? run.startedAt ?? run.updatedAt;
    if (!slot) seen.set(run.id, {at,published:false});
    rows.push({type:"work", id:"work:"+run.id, runId:run.id, botId:run.botId, at, run});
  }
  if (!seen.size) return rows;
  const timestamp = row => Date.parse((row.runId && seen.get(row.runId)?.at) || row.at) || 0;
  return rows.sort((a,b) => timestamp(a) - timestamp(b));
}
function GroupWorkReply({run, room, name, remote, onReload, member}) {
  const [busy,setBusy]=useState(false), [failure,setFailure]=useState("");
  const lock=useRef(false);
  const recovery=room.teamMessageFeedback?.find(x=>x.recoveredRunId===run.id);
  const failed=run.status==="failed";
  const archived=failed && /session ([\da-f-]{36}) is archived\b/iu.test(run.error??run.lastError??"");
  const phase=failed ? "failed" : run.status==="completed" ? "publishing" : run.groupWork?.phase ?? (run.status==="queued" ? "queued" : "checking");
  const fullText=run.groupWork?.text;
  const issue=run.error??run.lastError??"";
  const modelIssue=/宿主待授权|模型.*授权|缺少凭据|missing.credentials|UNAUTHORIZED|credential/i.test(issue)?"宿主待授权，请核对该 Bot 在 DP 中选择的模型":
    /DP 模型调用失败|指定模型调用失败|模型目录已变化/.test(issue)?"DP 模型调用失败，请检查该提供方":undefined;
  const label=recovery?(recovery.reason??recovery.receipt?.text??"这条消息已接回原单。"):failed ? archived ? "发送时原 Codex 对话已归档，模型未启动" :
    modelIssue ?? (run.failureKind==="timeout" ? "等待回复超时" : run.failureKind==="no-progress" ? "长时间没有新进展" : "这次回复失败") :
    phase==="publishing" ? "正在载入回复…" : fullText?.replace(/^[^：]*：/u,"") ?? (phase==="queued" ? "已排队，尚未开工" : "正在核对原回合状态");
  async function retry() {
    if (lock.current) return;
    lock.current=true; setBusy(true); setFailure("");
    try { await remote.continueTeamTask({roomId:room.id,messageId:run.originMessageId,mode:"retry-message",
      runId:run.id,expectedRevision:run.controlRevision}); }
    catch (error) { setFailure(error instanceof Error ? error.message : String(error)); }
    finally { try {await onReload?.();} finally {lock.current=false;setBusy(false);} }
  }
  return jsxs("div",{className:"br-bubble br-bot-bubble br-work-bubble","data-work-run":run.id,"data-work-phase":phase,
    children:[
      jsx("span",{role:"status","aria-live":"polite","aria-label":name+"："+label,children:label}),
      member?.action && jsx(GroupMemberReceipt,{member,name,roomId:room.id,messageId:run.originMessageId,remote,onReload}),
      failed && !recovery && !member && jsx("button",{type:"button",className:"br-retry",disabled:busy||!!run.stop&&run.stop.state!=="confirmed",
        id:"group-retry-"+run.id,title:run.error||label,"data-retry-run":run.id,onClick:()=>void retry(),children:busy?"正在重试…":"重试这条消息"}),
      failure && jsx("span",{role:"alert",children:failure})
    ]});
}
function GroupMessageFeedback({entry,room,runs,bots,remote,onReload}){
 const messageId=entry.messageId??entry.id;
 const [busy,setBusy]=useState(false),[failure,setFailure]=useState(""),[selected,select]=useState("");
 const [now,setNow]=useState(Date.now);
 const lock=useRef(false);
 const choice=room.continuationRequests?.find(row=>row.messageId===messageId);
 const deadline=Date.parse(choice?.expiresAt);
 useEffect(()=>{
  setNow(Date.now());
  if(!choice||choice.closedAt||!Number.isFinite(deadline))return;
  const t=setTimeout(()=>setNow(Date.now()),Math.max(0,deadline-Date.now())+10);
  return ()=>clearTimeout(t);
 },[messageId,deadline,choice?.closedAt]);
 const open=choice&&!choice.closedAt&&deadline>now;
 const mine=runs.filter(run=>run.originMessageId===messageId);
 const feedback=room.teamMessageFeedback?.find(row=>row.messageId===messageId);
  const review=room.mentionSequences?.find(task=>task.activeRequestId===messageId||task.id==="thread:"+messageId)?.reviewReceipt;
 const attention=room.teamChatAttention?.find(row=>row.messageId===messageId);
 const members=room.teamMemberReceipts?.find(row=>row.messageId===messageId)?.members;
 const visibleMembers=members?.filter(member=>!mine.some(run=>run.id===member.dispatchId &&
   ["queued","running","failed"].includes(run.status)));
 const nameOf=id=>groupName(bots.find(bot=>bot.id===id));
 async function act(input){
  if(lock.current)return;
  lock.current=true;setBusy(true);setFailure("");
  try{await remote.continueTeamTask({roomId:room.id,messageId,...input});}
  catch(error){setFailure(error instanceof Error?error.message:String(error));}
  finally{try{await onReload?.();}finally{lock.current=false;setBusy(false);}}
 }
 return jsxs(Fragment,{children:[
  !!visibleMembers?.length&&jsx("div",{className:"br-members","aria-label":"成员回执",children:visibleMembers.map(member=>
    jsx(GroupMemberReceipt,{member,name:nameOf(member.botId),roomId:room.id,messageId,remote,onReload},member.botId))}),
  open&&jsxs("div",{className:"br-picker","data-task-continuation":messageId,children:[
   jsx("div",{className:"br-picker-title",children:"接着做哪一件？"}),
   jsx("p",{className:"br-fine",children:"30 秒后收起，可以照常发消息。"}),
   ...choice.choices.map(item=>jsxs("label",{className:"br-option",children:[
    jsx("input",{type:"radio",name:"task-"+messageId,value:item.taskKey,checked:selected===item.taskKey,
     onChange:()=>{select(item.taskKey);if(choice.intent==="append")void act({taskKey:item.taskKey});}}),
    jsx("span",{children:item.label||"原任务"})
   ]},item.taskKey)),
   jsxs("div",{className:"br-btn-row",children:[
    jsx("button",{type:"button",className:"br-button br-primary",disabled:busy||!selected,
     onClick:()=>void act({taskKey:selected}),children:busy?"处理中…":"继续这件事"}),
    jsx("button",{type:"button",className:"br-button",disabled:busy,
     onClick:()=>void act({mode:"cancel-selection"}),children:"取消"})
   ]})
  ]}),
  choice&&!open&&!choice.selectedTaskKey&&jsx("span",{className:"br-delivery",children:
   choice.closedReason==="cancelled"?"已取消。":
   choice.closedReason==="superseded"?"已收起，按新消息处理。":"选择已过期。"}),
     review?.text&&jsx("span",{className:"br-delivery","data-review-phase":review.phase,children:review.text}),
   feedback?.receipt&&jsx("span",{className:"br-delivery",children:feedback.receipt.text}),
  feedback?.reason&&jsx("span",{className:"br-delivery",role:"status",children:feedback.reason}),
  feedback?.close&&jsx("span",{className:"br-delivery","data-thread-close":feedback.close.taskId,children:
   feedback.close.state==="closed"?"这件事已结束。":feedback.close.state==="stopping"?"正在等原回合停下来。":"等待群队长处理…"}),
  attention?.action&&jsx("button",{type:"button",className:"br-button br-primary",disabled:busy,
   onClick:()=>void act({mode:"continue-chat",expectedAllowance:attention.allowance}),children:"让下一位接着说"}),
  failure&&jsx("span",{className:"br-delivery",role:"alert",children:failure})
 ]});
}
let currentReminderRoute=null;
const reminderListeners=new Set();
function showReminderRoute(value){
 currentReminderRoute=value;
 for(const listener of reminderListeners)listener(value);
}
function useReminderRoute(){
 const [value,setValue]=useState(currentReminderRoute);
 useEffect(()=>{reminderListeners.add(setValue);setValue(currentReminderRoute);return ()=>reminderListeners.delete(setValue);},[]);
 return value;
}
function installReminderNavigation(remote,selectPanel){
 let stop=false,busy=false,cancelledRoute=null,timer,reported=false;
 async function check(){
  if(stop||busy||document.hidden||!document.hasFocus())return;
  busy=true;
  try{
   if(!reported){reported=true;await remote.taskReminder({op:"client-ready",build:GROUP_CHAT_BUILD,desktop:/Electron\//u.test(navigator.userAgent)}).catch(()=>{});}
   const {workspaceId,route}=await remote.taskReminder({op:"poll"});
   if(!route||stop||route.id===cancelledRoute)return;
   if(currentReminderRoute?.id===route.id){if(!currentReminderRoute.located)selectPanel();return;}
   let result;
   try{result=await remote.taskReminder({op:"target",key:route.key});}
   catch(error){
    if(!stop){selectPanel();showReminderRoute({id:route.id,error:error?.message??String(error),key:route.key});
     await remote.taskReminder({op:"forget-route",routeId:route.id,key:route.key});cancelledRoute=route.id;}
    return;
   }
   if(stop||result.event.workspaceId!==workspaceId||result.event.key!==route.key)return;
   selectPanel();showReminderRoute({...result,id:route.id});
  }catch{/* The host and the layout can be loading after a cold launch. */}
  finally{busy=false;}
 }
 const schedule=()=>{clearTimeout(timer);timer=setTimeout(check,35);};
 const repeat=setInterval(check,1600);
 window.addEventListener("focus",schedule);
 document.addEventListener("visibilitychange",schedule);
 window.addEventListener("dsh-bots-reminder-open",schedule);
 check();
 return ()=>{stop=true;clearTimeout(timer);clearInterval(repeat);window.removeEventListener("focus",schedule);window.removeEventListener("dsh-bots-reminder-open",schedule);document.removeEventListener("visibilitychange",schedule);};
}
